      -- ============================================  -- Single Procedure for Budget and Sub-Budget Allocations  -- ============================================  CREATE PROCEDURE [bud].[CreateMonthlyAllocations]      @budgetId INT,      @allocationMonth DATE,  -- Should be first day of month (e.g., '2025-01-01')      @budgetAllocatedAmount DECIMAL(15, 2) = 0.00,  -- Amount for main budget      @budgetNotes NVARCHAR(MAX) = NULL,      @subBudgetAllocations bud.MonthlyAllocationTableType READONLY  -- Sub-budget allocations  AS  BEGIN      SET NOCOUNT ON;            BEGIN TRY          BEGIN TRANSACTION;                    -- Validate budget exists          IF NOT EXISTS (SELECT 1 FROM bud.Budgets WHERE budgetId = @budgetId)          BEGIN              RAISERROR('Budget ID %d does not exist', 16, 1, @budgetId);              RETURN;          END                    -- Validate allocation month (should be first day of month)          IF DAY(@allocationMonth) != 1          BEGIN              RAISERROR('Allocation month must be the first day of the month', 16, 1);              RETURN;          END                    -- Step 1: Create Budget Monthly Allocation (if amount > 0)          IF @budgetAllocatedAmount > 0          BEGIN              -- Check if allocation already exists for this month              IF EXISTS (                  SELECT 1 FROM bud.BudgetMonthlyAllocations                   WHERE budgetId = @budgetId AND allocationMonth = @allocationMonth              )              BEGIN                  -- Update existing allocation                  UPDATE bud.BudgetMonthlyAllocations                  SET                       allocatedAmount = @budgetAllocatedAmount,                      notes = @budgetNotes,                      updatedAt = GETDATE()                  WHERE budgetId = @budgetId AND allocationMonth = @allocationMonth;              END              ELSE              BEGIN                  -- Insert new allocation                  INSERT INTO bud.BudgetMonthlyAllocations (budgetId, allocationMonth, allocatedAmount, notes)                  VALUES (@budgetId, @allocationMonth, @budgetAllocatedAmount, @budgetNotes);              END          END                    -- Step 2: Create Sub-Budget Monthly Allocations          IF EXISTS (SELECT 1 FROM @subBudgetAllocations)          BEGIN              -- Validate all sub-budgets belong to the specified budget              IF EXISTS (                  SELECT 1 FROM @subBudgetAllocations sba                  WHERE sba.subBudgetId NOT IN (                      SELECT subBudgetId FROM bud.SubBudgets WHERE budgetId = @budgetId                  )              )              BEGIN                  RAISERROR('One or more sub-budget IDs do not belong to the specified budget', 16, 1);                  ROLLBACK TRANSACTION;                  RETURN;              END                            -- Insert or Update sub-budget allocations              MERGE bud.SubBudgetMonthlyAllocations AS target              USING @subBudgetAllocations AS source              ON target.subBudgetId = source.subBudgetId                   AND target.allocationMonth = @allocationMonth              WHEN MATCHED THEN                  UPDATE SET                       allocatedAmount = source.allocatedAmount,                      notes = source.notes,                      updatedAt = GETDATE()              WHEN NOT MATCHED THEN                  INSERT (subBudgetId, allocationMonth, allocatedAmount, notes)                  VALUES (source.subBudgetId, @allocationMonth, source.allocatedAmount, source.notes);          END                    COMMIT TRANSACTION;                    -- Return success message with summary          SELECT               @budgetId AS budgetId,              @allocationMonth AS allocationMonth,              @budgetAllocatedAmount AS budgetAllocatedAmount,              (SELECT COUNT(*) FROM @subBudgetAllocations) AS subBudgetAllocationsCreated,              (SELECT SUM(allocatedAmount) FROM @subBudgetAllocations) AS totalSubBudgetAmount,              'Allocations created/updated successfully' AS message;                    END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;                        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();          DECLARE @ErrorSeverity INT = ERROR_SEVERITY();          DECLARE @ErrorState INT = ERROR_STATE();                    RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);      END CATCH  END
